public class ZipArchiveInputStream_getNextZipEntry_TriageGen0Test {

    private static final int LFH_SIG = 0x04034b50;
    private static final int CFH_SIG = 0x02014b50;
    private static final int AED_SIG = 0x06054b50;

    /**
     * Helper to build a raw LFH buffer for testing.
     */
    private byte[] createLFHBuffer(int sig, int method, boolean hasDataDescriptor, int fileNameLen, int extraLen, boolean utf8) {
        int headerSize = 30; // up to CRC/Size/CompressedSize
        if (hasDataDescriptor) {
            headerSize = 30; 
        }

        // Total size calculation:
        // Sig(4) + Ver(2) + Flags(2) + Method(2) + Time(4) + CRC(4) + CSize(4) + Size(4) + NameLen(2) + ExtraLen(2)
        int totalSize = 30 + fileNameLen + extraLen;
        ByteBuffer bb = ByteBuffer.allocate(totalSize).order(ByteOrder.LITTLE_ENDIAN);

        bb.putInt(sig);
        bb.putShort((short) 0x0200); // Version 2.0

        short flags = 0;
        if (utf8) flags |= 0x0800;
        if (hasDataDescriptor) flags |= 0x0008;
        bb.putShort(flags);

        bb.putShort((short) method);
        bb.putInt(0); // Time

        if (!hasDataDescriptor) {
            bb.putInt(0); // CRC
            bb.putInt(10); // Compressed Size
            bb.putInt(10); // Size
        } else {
            bb.position(bb.position() + 12); // Skip CRC/CSize/Size if descriptor used
        }

        bb.putShort((short) fileNameLen);
        bb.putShort((short) extraLen);

        byte[] name = new byte[fileNameLen];
        if (fileNameLen > 0) System.arraycopy("test.txt".getBytes(), 0, name, 0, Math.min(fileNameLen, 8));
        bb.put(name);

        byte[] extra = new byte[extraLen];
        bb.put(extra);

        return bb.array();
    }

    @Test
    public void testGetNextZipEntry_NullWhenClosed() throws IOException {
        InputStream is = new ByteArrayInputStream(new byte[0]);
        ZipArchiveInputStream zais = new ZipArchiveInputStream(is);
        zais.close();
        assertNull(zais.getNextZipEntry());
    }

    @Test
    public void testGetNextZipEntry_NullWhenHitCentralDirectory() throws IOException {
        byte[] buffer = createLFHBuffer(CFH_SIG, 0, false, 0, 0, false);
        InputStream is = new ByteArrayInputStream(buffer);
        ZipArchiveInputStream zais = new ZipArchiveInputStream(is);
        assertNull(zais.getNextZipEntry());
    }

    @Test
    public void testGetNextZipEntry_NullWhenHitAED() throws IOException {
        byte[] buffer = createLFHBuffer(AED_SIG, 0, false, 0, 0, false);
        InputStream is = new ByteArrayInputStream(buffer);
        ZipArchiveInputStream zais = new ZipArchiveInputStream(is);
        assertNull(zais.getNextZipEntry());
    }

    @Test
    public void testGetNextZipEntry_ThrowsExceptionOnInvalidSignature() throws IOException {
        byte[] buffer = createLFHBuffer(0x12345678, 0, false, 0, 0, false);
        InputStream is = new ByteArrayInputStream(buffer);
        ZipArchiveInputStream zais = new ZipArchiveInputStream(is);
        try {
            zais.getNextZipEntry();
            fail("Expected ZipException");
        } catch (ZipException e) {
            assertTrue(e.getMessage().contains("Unexpected record signature"));
        }
    }

    @Test
    public void testGetNextZipEntry_EOF() throws IOException {
        InputStream is = new ByteArrayInputStream(new byte[0]);
        ZipArchiveInputStream zais = new ZipArchiveInputStream(is);
        assertNull(zais.getNextZipEntry());
    }

    @Test
    public void testGetNextZipEntry_SuccessNormal() throws IOException {
        byte[] buffer = createLFHBuffer(LFH_SIG, 0, false, 8, 0, false);
        InputStream is = new ByteArrayInputStream(buffer);
        ZipArchiveInputStream zais = new ZipArchiveInputStream(is);

        ZipArchiveEntry entry = zais.getNextZipEntry();
        assertNotNull(entry);
        assertEquals("test.txt", entry.getName());
    }

    @Test
    public void testGetNextZipEntry_SuccessWithDataDescriptor() throws IOException {
        // hasDataDescriptor = true
        byte[] buffer = createLFHBuffer(LFH_SIG, 0, true, 8, 0, false);
        InputStream is = new ByteArrayInputStream(buffer);
        ZipArchiveInputStream zais = new ZipArchiveInputStream(is);

        ZipArchiveEntry entry = zais.getNextZipEntry();
        assertNotNull(entry);
    }

    @Test
    public void testGetNextZipEntry_SuccessUTF8() throws IOException {
        byte[] buffer = createLFHBuffer(LFH_SIG, 0, false, 8, 0, true);
        InputStream is = new ByteArrayInputStream(buffer);
        ZipArchiveInputStream zais = new ZipArchiveInputStream(is);

        ZipArchiveEntry entry = zais.getNextZipEntry();
        assertNotNull(entry);
    }

    @Test
    public void testGetNextZipEntry_MultipleEntries() throws IOException {
        byte[] entry1 = createLFHBuffer(LFH_SIG, 0, false, 4, 0, false);
        byte[] entry2 = createLFHBuffer(LFH_SIG, 0, false, 4, 0, false);

        ByteBuffer bb = ByteBuffer.allocate(entry1.length + entry2.length);
        bb.put(entry1);
        bb.put(entry2);

        InputStream is = new ByteArrayInputStream(bb.array());
        ZipArchiveInputStream zais = new ZipArchiveInputStream(is);

        assertNotNull(zais.getNextZipEntry());
        assertNotNull(zais.getNextZipEntry());
        assertNull(zais.getNextZipEntry());
    }

